const BOOKMOJI_ALIAS = {"400pages":"400","addictionthemes":"drugsandalcohol","amnesia":"cerebral","atmospheric":"creepy","characterdriven":"literary","dark":"creepy","darkhumor":"snarky","drugalcoholuse":"drugsandalcohol","dualtimelines":"nonlineartimeline","famousauthor":"wellknown","femalefriendships":"femalefriendship","firstperson":"literary","foundfamily":"familydrama","graphicviolence":"graphiccontent","grief":"sad","gritty":"rugged","identity":"cerebral","magicalrealism":"magical","multigenerational":"familydrama","murdermystery":"whodunit","periodismo":"academic","rebelion":"war","revenge":"murder","romancesubplot":"romance","satirical":"snarky","secta":"creepy","serialkiller":"murder","sisterdynamic":"siblings","strongfemalelead":"feminist","suburbandrama":"suburban","suspenseful":"catandmouse","tearjerker":"sad","techworld":"techie","teens":"teen","twisty":"puzzle","under200pages":"under200","unhinged":"scary","wittybanter":"snarky"};

/* ilustraciones de tropes (BOTM bookmoji) recoloreadas a shades de verde. */
function bookmojiKey(t){ return String(t||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,''); }
function bookmojiSVG(trope){
  const k=bookmojiKey(trope);
  if(BOOKMOJI[k]) return BOOKMOJI[k];
  if(BOOKMOJI_ALIAS[k] && BOOKMOJI[BOOKMOJI_ALIAS[k]]) return BOOKMOJI[BOOKMOJI_ALIAS[k]];
  const words=k.match(/[a-z]{4,}/g)||[];
  for(const w of words){ const hit=Object.keys(BOOKMOJI).find(kk=>kk.includes(w)); if(hit) return BOOKMOJI[hit]; }
  return BOOKMOJI.literary || Object.values(BOOKMOJI)[0] || '';
}
function bookmojiHTML(trope, cls){ return '<span class="bmj '+(cls||'')+'">'+bookmojiSVG(trope)+'</span>'; }

